import { sources } from "./sources";
import type { Source } from "@/components/content/Prose";

// Downloadable registration forms ("Ausbildungsvertrag") and, per class, what
// a student has to bring in. The PDFs in public/formulare/ are generated by
// scripts/generate-forms.py from the owner's paper forms (2026-10-14) — see
// knowledge/content-editing.md → "Forms". Only classes with a real paper
// form get a download; everything else is "Vertrag im Büro".

export type Checklist = {
  item: string;
  where: string;
  link?: { text: string; source: Source };
};

export type RegistrationForm = {
  id: string;
  title: string;
  file: `/formulare/${string}.pdf`;
  // Topic page the class belongs to (the forms section links back to it).
  classPage: `/${string}`;
  classPageLabel: string;
  intro: string;
  // What to bring to the office together with the form.
  bring: Checklist[];
  // What happens at the authority (Führerscheinstelle) — before or after.
  authority: { title: string; steps: string[]; links: Source[] };
  note?: string;
};

const ausweis: Checklist = {
  item: "Personalausweis oder Reisepass",
  where: "Bei ausländischem Pass ggf. zusätzlich Meldebescheinigung",
};
const passfoto: Checklist = {
  item: "Biometrisches Passfoto",
  where: "Fotograf oder Fotoautomat – wie für den Personalausweis",
};
const sehtest: Checklist = {
  item: "Sehtest-Bescheinigung (nicht älter als 2 Jahre)",
  where: "Optiker oder Augenarzt (amtlich anerkannte Sehteststelle)",
  link: { text: "Rechtsgrundlage: § 12 FeV", source: sources.fev12 },
};
const ersteHilfe: Checklist = {
  item: "Nachweis Erste-Hilfe-Kurs (9 Unterrichtseinheiten)",
  where: "z. B. DRK, ASB, Johanniter, Malteser – in Stuttgart u. a. beim DRK-Kreisverband",
  link: { text: "Kurse beim DRK Stuttgart", source: sources.drkStuttgart },
};
const vorhandenerFuehrerschein: Checklist = {
  item: "Bei Erweiterung: dein aktueller Führerschein",
  where: "Daten trägst du unter „FS ausgestellt von / Am / Führerscheinnummer“ ein",
};

